TEMPLATES = {
    '404.html': '{% extends "base.html" %}\n{% block title %}Not found{% endblock %}\n{% block content %}\n<section class="page-hero missing">\n  <p class="kicker"><span>404</span></p>\n  <h1>That page is not in the index.</h1>\n  <p class="lede">The lab site has a short map. Start from the work, or search.</p>\n  <div class="hero-actions">\n    <a class="btn btn-dark" href="{{ url_for(\'home\') }}">Back to the lab</a>\n    <a class="btn btn-line" href="{{ url_for(\'publications\') }}">Browse papers</a>\n  </div>\n</section>\n{% endblock %}\n',
    'about.html': '{% extends "base.html" %}\n{% block title %}About{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>About</span><span>Faculty of Dentistry</span></p>\n  <h1>{{ about.kicker }}</h1>\n  <p class="lede">{{ about.lead }}</p>\n</header>\n\n<section class="section about-layout">\n  <div class="about-copy">\n    <img class="about-photo reveal" src="{{ url_for(\'static\', filename=director.portrait) }}" alt="Anil Kishen in the laboratory">\n    {% for paragraph in about.paragraphs %}\n      <p class="prose reveal">{{ paragraph }}</p>\n    {% endfor %}\n    <blockquote class="pull-quote reveal">{{ about.question }}</blockquote>\n  </div>\n  <aside class="about-aside reveal">\n    <p class="eyebrow">At a glance</p>\n    <dl>\n      {% for stat in stats %}\n        <div>\n          <dt>{{ stat.label }}</dt>\n          <dd>{{ stat.value }}{{ stat.suffix }}</dd>\n        </div>\n      {% endfor %}\n    </dl>\n    <p class="aside-note">Counts follow the public biography: articles, chapters, books, and citations.</p>\n  </aside>\n</section>\n\n<section class="section principles">\n  <article class="reveal">\n    <span>01</span>\n    <h2>From mechanism to mouth</h2>\n    <p>Models of infection, immunity, and mechanics are only useful if they change a treatment decision.</p>\n  </article>\n  <article class="reveal">\n    <span>02</span>\n    <h2>A room that argues</h2>\n    <p>Clinicians, engineers, and biologists share one bench. Ideas are expected to survive the person next to them.</p>\n  </article>\n  <article class="reveal">\n    <span>03</span>\n    <h2>Train the next lead</h2>\n    <p>Mentorship is a research output. Graduate students and fellows leave able to run a question of their own.</p>\n  </article>\n</section>\n\n<section class="section director-strip">\n  <div>\n    <p class="eyebrow">Principal investigator</p>\n    <h2>{{ director.name }}, {{ director.credentials }}</h2>\n    <p class="prose">Professor and Canada Research Chair (Tier 1) in Oral Health Nanomedicine.</p>\n  </div>\n  <a class="btn btn-dark" href="{{ url_for(\'people\') }}">Full profile <span aria-hidden="true">→</span></a>\n</section>\n{% endblock %}\n',
    'awards.html': '{% extends "base.html" %}\n{% block title %}Awards{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>Awards</span><span>Inventions to benefit patient care</span></p>\n  <h1>Recognition for the work, and for the people who did it with him.</h1>\n  <p class="lede">Team prizes mark supervised projects. Personal honors mark lectureships, chairs, and a body of papers.</p>\n</header>\n\n<section class="section">\n  <div class="filter-row">\n    <a href="{{ url_for(\'awards\') }}" {% if scope == \'all\' %}aria-current="true"{% endif %}>All</a>\n    <a href="{{ url_for(\'awards\', scope=\'team\') }}" {% if scope == \'team\' %}aria-current="true"{% endif %}>Team</a>\n    <a href="{{ url_for(\'awards\', scope=\'personal\') }}" {% if scope == \'personal\' %}aria-current="true"{% endif %}>Personal</a>\n  </div>\n  <ol class="timeline">\n    {% for award in awards %}\n      <li class="reveal" id="{{ award.year }}">\n        <time>{{ award.year }}</time>\n        <div>\n          <span class="tag">{{ award.scope }}</span>\n          <h2>{{ award.title }}</h2>\n          {% if award.detail %}<p>{{ award.detail }}</p>{% endif %}\n        </div>\n      </li>\n    {% endfor %}\n  </ol>\n</section>\n{% endblock %}\n',
    'base.html': '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>{% block title %}Kishen Lab{% endblock %} · Oral health nanomedicine</title>\n  <meta name="description" content="Kishen Lab at the University of Toronto Faculty of Dentistry. Biologically based strategies for biofilm-mediated infection, regenerative endodontics, and oral health nanomedicine.">\n  <link rel="icon" href="{{ url_for(\'static\', filename=\'favicon.svg\') }}" type="image/svg+xml">\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400;0,6..72,500;0,6..72,600;1,6..72,400;1,6..72,500&family=Outfit:wght@300;400;500;600&display=swap" rel="stylesheet">\n  <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/site.css\') }}">\n  <script type="application/ld+json">\n  {\n    "@context": "https://schema.org",\n    "@type": "ResearchOrganization",\n    "name": "Kishen Lab",\n    "email": "{{ lab.email }}",\n    "telephone": "{{ lab.phone }}",\n    "parentOrganization": "University of Toronto Faculty of Dentistry",\n    "address": {\n      "@type": "PostalAddress",\n      "streetAddress": "124 Edward Street, Lab 510A",\n      "addressLocality": "Toronto",\n      "addressRegion": "ON",\n      "postalCode": "M5G 1G6",\n      "addressCountry": "CA"\n    }\n  }\n  </script>\n</head>\n<body data-page="{{ page }}">\n  <div class="logo-wash" aria-hidden="true">\n    <div class="logo-wash-move" data-logo-wash>\n      <img src="{{ url_for(\'static\', filename=\'images/logo.png\') }}" alt="">\n    </div>\n  </div>\n  <a class="skip" href="#content">Skip to content</a>\n  <div class="progress" data-progress aria-hidden="true"></div>\n\n  <header class="nav" data-nav>\n    <a class="brand" href="{{ url_for(\'home\') }}" aria-label="Kishen Lab, home">\n      <img src="{{ url_for(\'static\', filename=\'images/logo.png\') }}" alt="">\n    </a>\n\n    <nav class="nav-links" aria-label="Primary">\n      {% for label, endpoint in nav %}\n        <a href="{{ url_for(endpoint) }}" {% if page == endpoint %}aria-current="page"{% endif %}>{{ label }}</a>\n      {% endfor %}\n    </nav>\n\n    <div class="nav-tools">\n      <button class="search-open" type="button" data-search-open aria-label="Search" aria-haspopup="dialog">\n        <svg class="search-icon" viewBox="0 0 24 24" aria-hidden="true">\n          <circle cx="11" cy="11" r="6" fill="none" stroke="currentColor" stroke-width="1.8"/>\n          <path d="M15.5 15.5L20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>\n        </svg>\n        <span>Search</span>\n        <kbd>/</kbd>\n      </button>\n      <a class="nav-cta" href="{{ url_for(\'contact\') }}">Visit</a>\n      <button class="nav-toggle" type="button" data-menu aria-expanded="false" aria-controls="mobile-nav">\n        <span class="sr">Menu</span>\n        <i></i><i></i>\n      </button>\n    </div>\n  </header>\n\n  <div class="mobile-nav" id="mobile-nav" data-mobile hidden>\n    <nav aria-label="Mobile">\n      {% for label, endpoint in nav %}\n        <a href="{{ url_for(endpoint) }}" {% if page == endpoint %}aria-current="page"{% endif %}>\n          <span>0{{ loop.index }}</span>{{ label }}\n        </a>\n      {% endfor %}\n    </nav>\n  </div>\n\n  <div class="search-modal" data-search hidden>\n    <div class="search-card" role="dialog" aria-modal="true" aria-label="Search the lab">\n      <form role="search" data-search-form>\n        <label class="sr" for="site-search">Search</label>\n        <input id="site-search" type="search" placeholder="Search papers, people, awards…" autocomplete="off" data-search-input>\n      </form>\n      <div class="search-results" data-search-results></div>\n      <p class="search-hint">Papers, people, patents, awards, and news. Press Esc to close.</p>\n    </div>\n  </div>\n\n  <main id="content">\n    {% block content %}{% endblock %}\n  </main>\n\n  <footer class="footer">\n    <div class="footer-grid">\n      <div>\n        <img class="footer-logo" src="{{ url_for(\'static\', filename=\'images/logo.png\') }}" alt="The Kishen Lab">\n        <p class="footer-line">{{ lab.line }}</p>\n      </div>\n      <div>\n        <p class="eyebrow">Laboratory</p>\n        <p>{{ lab.room }}<br>{{ lab.place }}<br>{{ lab.street }}<br>{{ lab.city }}</p>\n      </div>\n      <div>\n        <p class="eyebrow">Correspondence</p>\n        <p><a href="mailto:{{ lab.email }}">{{ lab.email }}</a><br><a href="{{ lab.phone_href }}">{{ lab.phone }}</a></p>\n      </div>\n      <div>\n        <p class="eyebrow">Index</p>\n        <ul class="footer-links">\n          {% for label, endpoint in nav %}\n            <li><a href="{{ url_for(endpoint) }}">{{ label }}</a></li>\n          {% endfor %}\n        </ul>\n      </div>\n    </div>\n    <div class="footer-base">\n      <p>© {{ now_year }} Dr. Anil Kishen. An independent redesign of the public lab record.</p>\n      <a href="{{ lab.source }}">thekishenlab.org</a>\n    </div>\n  </footer>\n  <script src="{{ url_for(\'static\', filename=\'js/site.js\') }}" defer></script>\n</body>\n</html>\n',
    'contact.html': '{% extends "base.html" %}\n{% block title %}Contact{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>Contact</span><span>{{ lab.room }}</span></p>\n  <h1>Write to the laboratory.</h1>\n  <p class="lede">Students, collaborators, clinicians, and journalists. Mail also goes directly to {{ lab.email }}.</p>\n</header>\n\n<section class="section contact-layout">\n  <div class="contact-card">\n    {% if sent %}\n      <div class="sent" role="status">\n        <p class="eyebrow">Received</p>\n        {% if stored %}\n          <h2>The note is in the lab inbox on this machine.</h2>\n          <p>For a reply from the group itself, use <a href="mailto:{{ lab.email }}">{{ lab.email }}</a>.</p>\n        {% else %}\n          <h2>Email reaches the lab directly.</h2>\n          <p>Send the note to <a href="mailto:{{ lab.email }}">{{ lab.email }}</a>.</p>\n        {% endif %}\n      </div>\n    {% else %}\n      {% if error %}<p class="form-error" role="alert">{{ error }}</p>{% endif %}\n      <form method="post" class="contact-form" novalidate>\n        <label>Name <input name="name" type="text" required autocomplete="name"></label>\n        <label>Email <input name="email" type="email" required autocomplete="email"></label>\n        <label>I am writing as\n          <select name="role">\n            <option>Prospective student</option>\n            <option>Collaborator</option>\n            <option>Clinician</option>\n            <option>Journalist</option>\n            <option>Something else</option>\n          </select>\n        </label>\n        <label class="hp" aria-hidden="true">Company <input name="company" type="text" tabindex="-1" autocomplete="off"></label>\n        <label>Note <textarea name="message" rows="6" required placeholder="What would you like to work on?"></textarea></label>\n        <button class="btn btn-dark" type="submit">Send the note <span aria-hidden="true">→</span></button>\n      </form>\n    {% endif %}\n  </div>\n  <aside class="visit-card">\n    <p class="eyebrow">Where</p>\n    <address>\n      {{ lab.room }}<br>\n      {{ lab.place }}<br>\n      {{ lab.street }}<br>\n      {{ lab.city }}\n    </address>\n    <p><a href="{{ lab.maps }}">Open in maps</a></p>\n    <p class="eyebrow">Direct</p>\n    <p><a href="mailto:{{ lab.email }}">{{ lab.email }}</a><br><a href="{{ lab.phone_href }}">{{ lab.phone }}</a></p>\n  </aside>\n</section>\n{% endblock %}\n',
    'index.html': '{% extends "base.html" %}\n{% block title %}Kishen Lab{% endblock %}\n{% block content %}\n<section class="hero">\n  <div class="hero-grid">\n    <div class="hero-copy">\n      <h1 class="reveal">Kishen Lab</h1>\n      <p class="kicker reveal"><span>Lab 510A</span><span>Faculty of Dentistry, University of Toronto</span><span>Since the early 2000s</span></p>\n      <p class="lede reveal">A clinician-scientist’s laboratory for biofilm-mediated infection. Nanomedicine, regenerative endodontics, and the immune life of dental tissue — built to leave the bench.</p>\n      <div class="hero-actions reveal">\n        <a class="btn btn-light" href="{{ url_for(\'research\') }}">Read the research <span aria-hidden="true">→</span></a>\n        <a class="btn btn-ghost" href="{{ url_for(\'people\') }}">The people</a>\n      </div>\n      <blockquote class="hero-question reveal">\n        <p>Is drill-and-fill the right strategy for an organ this biologically adapted — or can the body be recruited to heal?</p>\n      </blockquote>\n    </div>\n    <figure class="hero-photo reveal">\n      <img src="{{ url_for(\'static\', filename=\'images/lab-group.jpeg\') }}" alt="Members of the Kishen Lab together in the laboratory">\n    </figure>\n  </div>\n  <dl class="stats">\n    {% for stat in stats %}\n      <div class="stat reveal">\n        <dt>{{ stat.label }}</dt>\n        <dd data-count="{{ stat.value }}" data-suffix="{{ stat.suffix }}">0{{ stat.suffix }}</dd>\n      </div>\n    {% endfor %}\n  </dl>\n</section>\n\n<div class="funders" aria-label="Supporting agencies">\n  <p>Supporting agencies</p>\n  <ul>\n    {% for fund in funds %}\n      <li><img src="{{ url_for(\'static\', filename=fund.file) }}" alt="{{ fund.name }}"></li>\n    {% endfor %}\n  </ul>\n</div>\n\n<section class="section contents-section">\n  <div class="section-head">\n    <p class="eyebrow">Contents</p>\n    <h2>A laboratory, indexed.</h2>\n  </div>\n  <ol class="contents">\n    <li class="reveal"><a href="{{ url_for(\'research\') }}"><span>01</span><strong>Research</strong><em>Four programs, from organoids to interferometry.</em></a></li>\n    <li class="reveal"><a href="{{ url_for(\'people\') }}"><span>02</span><strong>People</strong><em>Engineers, clinicians, and trainees in Lab 510A.</em></a></li>\n    <li class="reveal"><a href="{{ url_for(\'publications\') }}"><span>03</span><strong>Record</strong><em>Selected papers from a list of more than 250.</em></a></li>\n    <li class="reveal"><a href="{{ url_for(\'media\') }}"><span>04</span><strong>Dispatches</strong><em>From the Straits Times to the present.</em></a></li>\n  </ol>\n</section>\n\n<section class="section manifesto">\n  <div class="manifesto-grid">\n    <p class="eyebrow reveal">The premise</p>\n    <div>\n      <p class="pull reveal">The tooth is built by epithelium, neural crest, and mesoderm, then asked to chew while surrounded by microbes. Immunity protects it — and decides how it repairs.</p>\n      <p class="prose reveal">Kishen Lab is led by a clinician-scientist trained in both the clinic and biomedical engineering. For two decades the group has engineered biologically based approaches to bacterial biofilm-mediated infection, rather than treating the tooth as a cavity to be filled.</p>\n      <a class="text-link reveal" href="{{ url_for(\'about\') }}">The longer account <span aria-hidden="true">→</span></a>\n    </div>\n  </div>\n</section>\n\n<section class="section">\n  <div class="section-head">\n    <p class="eyebrow">Programs</p>\n    <h2>Where the work sits.</h2>\n  </div>\n  <div class="pillars">\n    {% for pillar in pillars %}\n      <article class="pillar reveal" style="--i: {{ loop.index }}">\n        <span class="pillar-num">{{ pillar.num }}</span>\n        <h3>{{ pillar.title }}</h3>\n        <p>{{ pillar.summary }}</p>\n        <a href="{{ url_for(\'research\') }}#{{ pillar.slug }}">Open the program</a>\n      </article>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section split-band">\n  <div>\n    <p class="eyebrow">Bench to care</p>\n    <h2>What has already left the lab.</h2>\n    <p class="prose">Clinical translation is part of the research design, not a slide at the end.</p>\n  </div>\n  <ul class="translations">\n    {% for item in translations %}\n      <li class="reveal">\n        <strong>{{ item.title }}</strong>\n        <span>{{ item.detail }}</span>\n      </li>\n    {% endfor %}\n  </ul>\n</section>\n\n<section class="section">\n  <div class="section-head row-head">\n    <div>\n      <p class="eyebrow">Selected record</p>\n      <h2>Recent papers.</h2>\n    </div>\n    <a class="text-link" href="{{ url_for(\'publications\') }}">Full index <span aria-hidden="true">→</span></a>\n  </div>\n  <div class="papers">\n    {% for paper in papers %}\n      <article class="paper reveal">\n        {% if paper.figure %}\n          <img class="paper-fig" src="{{ url_for(\'static\', filename=paper.figure) }}" alt="">\n        {% endif %}\n        <p class="paper-meta">{{ paper.year }} · {{ paper.journal }}</p>\n        <h3>{{ paper.title }}</h3>\n        <p class="paper-authors">{{ paper.authors }}</p>\n        <p>{{ paper.summary }}</p>\n      </article>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section news-section">\n  <div class="section-head row-head">\n    <div>\n      <p class="eyebrow">Dispatches</p>\n      <h2>Outside the journal.</h2>\n    </div>\n    <a class="text-link" href="{{ url_for(\'media\') }}">All coverage <span aria-hidden="true">→</span></a>\n  </div>\n  <div class="news-grid">\n    {% for story in news %}\n      <a class="news-card reveal" href="{{ story.href }}">\n        {% if story.image %}\n          <img src="{{ url_for(\'static\', filename=story.image) }}" alt="">\n        {% endif %}\n        <p>{{ story.outlet }} · {{ story.date }}</p>\n        <h3>{{ story.title }}</h3>\n        <span>Read the piece</span>\n      </a>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section voices" data-voices>\n  <p class="eyebrow">From the room</p>\n  <div class="voice-frame">\n    {% for item in testimonials %}\n      <blockquote class="voice {% if loop.first %}is-active{% endif %}" data-voice>\n        <p>“{{ item.quote }}”</p>\n        <footer>{{ item.by }}</footer>\n      </blockquote>\n    {% endfor %}\n  </div>\n  <div class="voice-dots" role="tablist" aria-label="Testimonials">\n    {% for item in testimonials %}\n      <button type="button" aria-label="Show testimonial {{ loop.index }}" {% if loop.first %}aria-current="true"{% endif %}></button>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="visit">\n  <div>\n    <p class="eyebrow">Correspondence</p>\n    <h2>Lab 510A, Edward Street.</h2>\n    <p>Faculty of Dentistry, University of Toronto. Prospective students, collaborators, and journalists are welcome to write.</p>\n  </div>\n  <div class="visit-actions">\n    <a class="btn btn-light" href="mailto:{{ lab.email }}">{{ lab.email }}</a>\n    <a class="btn btn-ghost" href="{{ url_for(\'contact\') }}">Write to the lab</a>\n  </div>\n</section>\n{% endblock %}\n',
    'media.html': '{% extends "base.html" %}\n{% block title %}Media{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>Media</span><span>Happenings</span></p>\n  <h1>The lab, as other people have told it.</h1>\n  <p class="lede">From a fiber-optic sensor in Singapore to the work in Toronto. Stories link out to the original piece when a public URL exists.</p>\n</header>\n\n<section class="section">\n  <div class="section-head">\n    <p class="eyebrow">Recent</p>\n    <h2>Longer dispatches.</h2>\n  </div>\n  <div class="feature-news">\n    {% for story in news %}\n      <a class="feature-card reveal" href="{{ story.href }}">\n        {% if story.image %}\n          <img src="{{ url_for(\'static\', filename=story.image) }}" alt="">\n        {% endif %}\n        <p>{{ story.outlet }} · {{ story.date }}</p>\n        <h3>{{ story.title }}</h3>\n        <span>{{ story.summary }}</span>\n      </a>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section">\n  <div class="section-head">\n    <p class="eyebrow">In print</p>\n    <h2>Pages and rooms.</h2>\n  </div>\n  <div class="cover-row">\n    {% for cover in covers %}\n      <figure class="reveal">\n        <img src="{{ url_for(\'static\', filename=cover.file) }}" alt="{{ cover.caption }}">\n        <figcaption>{{ cover.caption }}</figcaption>\n      </figure>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section">\n  <div class="section-head">\n    <p class="eyebrow">Archive</p>\n    <h2>Coverage since 2001.</h2>\n  </div>\n  <ul class="media-list">\n    {% for item in media %}\n      <li class="reveal">\n        <span>{{ item.year }}</span>\n        <div>\n          <p>{{ item.outlet }}</p>\n          {% if item.href %}\n            <a href="{{ item.href }}">{{ item.title }}</a>\n          {% else %}\n            <strong>{{ item.title }}</strong>\n          {% endif %}\n        </div>\n      </li>\n    {% endfor %}\n  </ul>\n</section>\n{% endblock %}\n',
    'people.html': '{% extends "base.html" %}\n{% block title %}People{% endblock %}\n{% block content %}\n<header class="page-hero people-hero">\n  <p class="kicker"><span>People</span><span>Lab 510A</span></p>\n  <h1>Current group</h1>\n</header>\n\n<section class="section" id="current">\n  <article class="lead">\n    <img src="{{ url_for(\'static\', filename=director.portrait) }}" alt="Anil Kishen">\n    <div>\n      <p class="role">{{ director.role }}</p>\n      <h2>{{ director.name }} <span>{{ director.credentials }}</span></h2>\n      <ul>\n        {% for title in director.titles %}\n          <li>{{ title }}</li>\n        {% endfor %}\n      </ul>\n      <p>Editorial: {{ director.editorial | join("; ") }}.</p>\n    </div>\n  </article>\n  <div class="people-grid">\n    {% for person in current %}\n      <article class="person reveal">\n        {% if person.photo %}\n          <img class="avatar" src="{{ url_for(\'static\', filename=person.photo) }}" alt="">\n        {% else %}\n          <div class="avatar" aria-hidden="true">{{ person.name.split()[0][0] }}{{ person.name.split()[-1][0] }}</div>\n        {% endif %}\n        <div>\n          <h3>{{ person.name }}{% if person.credentials %} <small>{{ person.credentials }}</small>{% endif %}</h3>\n          <p class="role">{{ person.role }}</p>\n          <p>{{ person.project }}</p>\n        </div>\n      </article>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section alumni" data-alumni>\n  <div class="section-head">\n    <p class="eyebrow">Alumni</p>\n    <h2>People who trained here.</h2>\n  </div>\n  <div class="filter-row" role="tablist" aria-label="Alumni groups">\n    {% for group in alumni %}\n      <button type="button" role="tab" data-alumni-tab="{{ group.id }}" {% if loop.first %}aria-selected="true"{% else %}aria-selected="false"{% endif %}>{{ group.label }}</button>\n    {% endfor %}\n  </div>\n  {% for group in alumni %}\n    <ul class="alumni-list" data-alumni-panel="{{ group.id }}" {% if not loop.first %}hidden{% endif %}>\n      {% for name in group.people %}\n        <li class="reveal">{{ name }}</li>\n      {% endfor %}\n    </ul>\n  {% endfor %}\n</section>\n{% endblock %}\n',
    'publications.html': '{% extends "base.html" %}\n{% block title %}Publications{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>Publications</span><span>{{ total }} in this index</span></p>\n  <h1>A reading list, not the whole library.</h1>\n  <p class="lede">Dr. Kishen’s public record is more than 250 papers. This index holds a curated set the lab itself highlights, plus recent 2025 work, and it can be searched.</p>\n</header>\n\n<section class="section">\n  <form class="finder" id="finder" action="{{ url_for(\'publications\') }}" method="get" role="search">\n    <label class="sr" for="q">Search papers</label>\n    <input id="q" name="q" type="search" value="{{ q }}" placeholder="Try organoid, macrophage, chitosan…">\n    <label class="sr" for="year">Year</label>\n    <select id="year" name="year">\n      <option value="">All years</option>\n      {% for y in years %}\n        <option value="{{ y }}" {% if year == y|string %}selected{% endif %}>{{ y }}</option>\n      {% endfor %}\n    </select>\n    <label class="sr" for="theme">Theme</label>\n    <select id="theme" name="theme">\n      <option value="">All themes</option>\n      {% for key, label in themes %}\n        <option value="{{ key }}" {% if theme == key %}selected{% endif %}>{{ label }}</option>\n      {% endfor %}\n    </select>\n    <button class="btn btn-dark" type="submit">Filter</button>\n  </form>\n  <p class="finder-count" data-count-label>{{ papers|length }} showing · {{ total }} indexed</p>\n\n  <div class="paper-index" data-paper-index>\n    {% if papers %}\n      {% for paper in papers %}\n        <article class="paper-row">\n          <div class="paper-year">{{ paper.year }}</div>\n          <div>\n            <p class="paper-meta">{{ paper.journal }}{% if paper.meta %} · {{ paper.meta }}{% endif %}</p>\n            <h2>{{ paper.title }}</h2>\n            <p class="paper-authors">{{ paper.authors }}</p>\n            {% if paper.figure %}\n              <img class="paper-fig wide" src="{{ url_for(\'static\', filename=paper.figure) }}" alt="">\n            {% endif %}\n            <p>{{ paper.summary }}</p>\n            {% if paper.doi %}\n              <a class="text-link" href="https://doi.org/{{ paper.doi }}">doi.org/{{ paper.doi }} <span aria-hidden="true">↗</span></a>\n            {% endif %}\n          </div>\n          <span class="tag">{{ paper.theme }}</span>\n        </article>\n      {% endfor %}\n    {% else %}\n      <p class="empty">Nothing in the index matches that filter. Try a broader word, or clear the year.</p>\n    {% endif %}\n  </div>\n</section>\n{% endblock %}\n',
    'research.html': '{% extends "base.html" %}\n{% block title %}Research{% endblock %}\n{% block content %}\n<header class="page-hero">\n  <p class="kicker"><span>Research</span><span>Discovery, translation, tools</span></p>\n  <h1>The biology, the material, and the mechanics.</h1>\n  <p class="lede">The lab studies dental tissues in order to build diagnostics, therapies, and materials that preserve and regenerate the tooth and what holds it.</p>\n</header>\n\n<figure class="focus-figure">\n  <img src="{{ url_for(\'static\', filename=\'images/focus.jpg\') }}" alt="Three panels of Kishen Lab work: nanoparticle targeting, cellular mechanisms of dental tissue, and immune modulation in the oral environment.">\n</figure>\n\n<nav class="anchor-nav" aria-label="Research sections">\n  {% for pillar in pillars %}\n    <a href="#{{ pillar.slug }}">{{ pillar.num }} {{ pillar.title }}</a>\n  {% endfor %}\n  <a href="#translation">Translation</a>\n  <a href="#patents">Patents</a>\n</nav>\n\n<section class="section program-list">\n  {% for pillar in pillars %}\n    <article class="program reveal" id="{{ pillar.slug }}">\n      <div class="program-index">\n        <span>{{ pillar.num }}</span>\n        <h2>{{ pillar.title }}</h2>\n      </div>\n      <div>\n        <p class="prose">{{ pillar.summary }}</p>\n        <ul>\n          {% for point in pillar.points %}\n            <li>{{ point }}</li>\n          {% endfor %}\n        </ul>\n      </div>\n    </article>\n  {% endfor %}\n</section>\n\n<section class="section">\n  <div class="section-head">\n    <p class="eyebrow">Basic science</p>\n    <h2>Three contributions underneath the themes.</h2>\n  </div>\n  <div class="basic-grid">\n    {% for item in basic %}\n      <article class="reveal">\n        <h3>{{ item.title }}</h3>\n        <p>{{ item.body }}</p>\n      </article>\n    {% endfor %}\n  </div>\n</section>\n\n<section class="section split-band" id="translation">\n  <div>\n    <p class="eyebrow">Clinical translation</p>\n    <h2>Inventions meant for a patient.</h2>\n    <p class="prose">{{ impact }}</p>\n  </div>\n  <ul class="translations">\n    {% for item in translations %}\n      <li class="reveal">\n        <strong>{{ item.title }}</strong>\n        <span>{{ item.detail }}</span>\n      </li>\n    {% endfor %}\n  </ul>\n</section>\n\n<section class="section" id="patents">\n  <div class="section-head">\n    <p class="eyebrow">Intellectual property</p>\n    <h2>Patents and applications.</h2>\n    <p class="prose patent-note">Granted patents and published applications naming Anil Kishen. Status follows the public listing on the lab site, including USPTO records.</p>\n  </div>\n  <div class="patent-list">\n    {% for patent in patents %}\n      <article class="patent reveal">\n        <div class="patent-top">\n          <span class="tag">{{ patent.status }}</span>\n          <span>{{ patent.date }}</span>\n        </div>\n        <h3>{{ patent.title }}</h3>\n        <p>{{ patent.summary }}</p>\n        <dl>\n          <div><dt>Number</dt><dd>{{ patent.number }}</dd></div>\n          <div><dt>Holder</dt><dd>{{ patent.holder }}</dd></div>\n          <div><dt>Inventors</dt><dd>{{ patent.inventors }}</dd></div>\n        </dl>\n      </article>\n    {% endfor %}\n  </div>\n</section>\n{% endblock %}\n',
}
